CREATE OR REPLACE FUNCTION public.offsite_config_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE k text; ids_old jsonb; ids_new jsonb; BEGIN IF jsonb_typeof(NEW.conteudo)<>'object' OR octet_length(NEW.conteudo::text)>1000000 THEN RAISE EXCEPTION 'Configuração inválida'; END IF; IF NEW.conteudo<>'{}' THEN IF jsonb_typeof(NEW.conteudo->'perguntas') IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.conteudo->'perguntas')<>9 OR jsonb_array_length(NEW.conteudo->'blocos')<>9 THEN RAISE EXCEPTION 'Mantenha nove etapas'; END IF; IF TG_OP='UPDATE' AND OLD.conteudo<>'{}' THEN FOREACH k IN ARRAY ARRAY['diretrizes','projetos','andamento','produtos','escolhas'] LOOP SELECT jsonb_agg(x->>'id') INTO ids_old FROM jsonb_array_elements(OLD.conteudo->k) x; SELECT jsonb_agg(x->>'id') INTO ids_new FROM jsonb_array_elements(NEW.conteudo->k) x; IF ids_old IS DISTINCT FROM ids_new THEN RAISE EXCEPTION 'Preserve identificadores e ordem dos itens'; END IF; END LOOP; SELECT jsonb_agg(p->>'id') INTO ids_old FROM jsonb_array_elements(OLD.conteudo->'perguntas') b CROSS JOIN LATERAL jsonb_array_elements(b) p; SELECT jsonb_agg(p->>'id') INTO ids_new FROM jsonb_array_elements(NEW.conteudo->'perguntas') b CROSS JOIN LATERAL jsonb_array_elements(b) p; IF ids_old IS DISTINCT FROM ids_new THEN RAISE EXCEPTION 'Preserve identificadores das perguntas'; END IF; END IF; END IF; NEW.atualizado_em:=now(); INSERT INTO offsite_historico(ator,acao,antes,depois) VALUES(auth.uid(),'configuracao',CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE NULL END,to_jsonb(NEW)); RETURN NEW; END $$;